mapper.select:
SELECT A.REORGID AS REORGID , A.REORGNAME AS REORGNAME, A.ORGID ORGID, A.ORGNAME ORGNAME FROM T_ECC_ORRELA A WHERE A.STAT='STAR'
AND A.REORGID=#{parentId}
ORDER BY A.ORGID DESC

SELECT B.ORGID, B.TITLEID, B.TITLENAME FROM T_ECC_ORMEMBER B WHERE B.STAT = 'STAR'
AND B.ORGID=#{orgId}
GROUP BY B.ORGID, B.TITLEID, B.TITLENAME ORDER BY B.ORGID DESC, B.TITLEID
